def branchNotebookFloorTicket(root, k):
    a=root
    out=[]
    def visit(node):
        if not node: return
        out.append(node.val)
        visit(node.left)
        visit(node.right)
    visit(a)
    return min(out,default=0)


java
class Solution {
  public int branchNotebookFloorTicket(TreeNode root, int k) {
    TreeNode a=root; List<Integer> out=new ArrayList<>();
    {class Walk {void visit(TreeNode node){if(node==null)return;out.add(node.val);visit(node.left);visit(node.right);}}new Walk().visit(a);}
    int answer=out.isEmpty()?0:out.get(0);for(int x:out)answer=Math.min(answer,x);return answer;
  }
}
